// typed_a4_check_rt.h: round A4's differential check (a4_typed_check.cpp, generated by tools/typed_lift2.py --check-tu;
// docs/decomp_a4.md). Only the check translation unit and the offline harness (tools/a4_harness.cpp) include it.
//
// A3's check (typed_a3_check_rt.h: two legs on logged memory, the reference a copy of the lifted text on a copy of the
// caller's context, its calls dispatched to the callees' lifted texts) in its own namespace (a4ck: its own overlay and
// counts, the "[a4]" line), with the VU0 interface compared: after the typed leg the generated check writes the typed
// function's VU0 outputs into a copy of the input context (ckTyCtx) and vuDiffer compares every VU0 register, ACC, Q,
// status and every GPR's upper half with the reference's context; a slot outside the interface must come out of the
// reference unchanged. The quadword accesses of both legs are two logged 8-byte halves (rd128 / wr128).
#pragma once

#define A3CK_NS a4ck
#define A3CK_LABEL "[a4]"
#define A4_CHECK_TU 1
#include "typed_a3_check_rt.h"
#include "typed_a4_rt.h"
